'use strict';

/*
 * Printouts: PDFs made by Chromium from the HTML templates in src/templates/printouts (Handlebars).
 *
 *   const { renderPdf } = require('../../shared/printouts');
 *   const buffer = await renderPdf('ratings-list', data, { landscape: true });
 *
 * `data` is what the template reads (see its `.sample.json` in docs/design/printouts, and "Printouts" in
 * docs/design/README.md). Always put `generatedBy` and `generatedAt` in it: they make the footer
 * "RESTRICTED — Nigerian Navy CIRERMS | Generated by: <name> | dd/mm/yyyy hh:mm" (Nigerian time, WAT).
 * `generatedAt` defaults to now. `options.landscape` sets `data.orientation` for a template that reads it
 * (static-table-list); the other templates fix their own orientation in their `head` partial.
 *
 * How it works: the template is filled with Handlebars (partials and helpers from the templates folder), and
 * loaded into a tab of ONE shared Chromium (browser.js). The page's own files (printout.css, fonts, the crest)
 * are answered from the app's disk through request interception, and every other request is refused, so
 * nothing is ever fetched from the internet. The footer is the `footer` partial (Page X of Y, every page);
 * the header block is in the page itself, on page 1 only.
 *
 * Settings (all optional, in .env, read by src/config): see `pdf` in src/config/index.js and README.md.
 * Errors are logged and thrown as an Error with status 500 (or 503 when the server is too busy); a render
 * never hangs: it has a timeout.
 */
const fs = require('fs');
const path = require('path');
const Handlebars = require('handlebars');
const config = require('../../config');
const browser = require('./browser');

const TEMPLATES_DIR = path.join(config.rootDir, 'src', 'templates', 'printouts');
// the crest is the app's own file, shared with the screens; the rest comes from the templates folder
const FILE_MAP = new Map([['assets/navy-logo.png', path.join(config.publicDir, 'assets', 'navy-logo.png')]]);
const ORIGIN = 'http://printouts.invalid';
const MIME = { '.css': 'text/css', '.woff2': 'font/woff2', '.png': 'image/png', '.svg': 'image/svg+xml', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg' };

const hbs = Handlebars.create();
require(path.join(TEMPLATES_DIR, 'helpers'))(hbs);
for (const f of fs.readdirSync(path.join(TEMPLATES_DIR, 'partials'))) {
  hbs.registerPartial(path.basename(f, '.hbs'), fs.readFileSync(path.join(TEMPLATES_DIR, 'partials', f), 'utf8'));
}

const compiled = new Map();
function template(name) {
  if (!/^[a-z0-9-]+$/.test(name)) throw new Error(`Unknown printout template "${name}".`);
  if (!compiled.has(name)) {
    const file = path.join(TEMPLATES_DIR, `${name}.hbs`);
    if (!fs.existsSync(file)) throw new Error(`Unknown printout template "${name}".`);
    compiled.set(name, hbs.compile(fs.readFileSync(file, 'utf8')));
  }
  return compiled.get(name);
}

let footerFont = null;
function footerHtml(data) {
  if (!footerFont) {
    footerFont = `data:font/woff2;base64,${fs.readFileSync(path.join(TEMPLATES_DIR, 'fonts', 'inter-latin-400-normal.woff2')).toString('base64')}`;
  }
  return hbs.compile(fs.readFileSync(path.join(TEMPLATES_DIR, 'partials', 'footer.hbs'), 'utf8'))({
    generatedBy: data.generatedBy,
    generatedAt: hbs.helpers.datetime(data.generatedAt || new Date()),
    fontData: footerFont,
  });
}

/** The file a page asks for, or null: only inside the templates folder (and the crest), never anywhere else. */
function fileFor(url) {
  if (!url.startsWith(`${ORIGIN}/`)) return null;
  const rel = decodeURIComponent(url.slice(ORIGIN.length + 1).split(/[?#]/)[0]);
  if (FILE_MAP.has(rel)) return FILE_MAP.get(rel);
  const full = path.resolve(TEMPLATES_DIR, rel);
  if (!full.startsWith(`${TEMPLATES_DIR}${path.sep}`) || !MIME[path.extname(full)] || !fs.existsSync(full)) return null;
  return full;
}

/**
 * Make a PDF from a template.
 * @param {string} name     template name, for example 'ratings-list' (src/templates/printouts/<name>.hbs)
 * @param {object} data     what the template reads, with generatedBy and generatedAt
 * @param {{landscape?: boolean, maxHtmlMb?: number}} [options]  maxHtmlMb: a printout that carries pictures (the User Guide's book) lifts the size limit
 * @returns {Promise<Buffer>}
 */
async function renderPdf(name, data, options = {}) {
  const input = { ...data };
  if (options.landscape !== undefined) input.orientation = options.landscape ? 'landscape' : 'portrait';
  const html = template(name)(input).replace('<head>', `<head><base href="${ORIGIN}/">`);
  const mb = Buffer.byteLength(html, 'utf8') / (1024 * 1024);
  const limit = options.maxHtmlMb || config.pdf.maxHtmlMb;
  if (mb > limit) {
    const e = new Error(`This printout is too large to make (${mb.toFixed(1)} MB; the limit is ${limit} MB). Narrow the list and try again.`);
    e.status = 400;
    throw e;
  }
  const footer = footerHtml(input);
  const started = Date.now();
  try {
    const pdf = await browser.withPage(async (page) => {
      await page.setRequestInterception(true);
      page.on('request', (req) => {
        const url = req.url();
        if (url.startsWith('data:') || url === 'about:blank') { req.continue(); return; }
        const file = fileFor(url);
        if (!file) { req.abort('blockedbyclient'); return; }
        // the page's own origin is opaque, so fonts need the allow-origin header
        req.respond({ status: 200, contentType: MIME[path.extname(file)], headers: { 'Access-Control-Allow-Origin': '*' }, body: fs.readFileSync(file) });
      });
      await page.setContent(html, { waitUntil: 'load', timeout: config.pdf.timeoutMs });
      await Promise.race([page.evaluate('document.fonts.ready'), new Promise((r) => setTimeout(r, config.pdf.fontWaitMs))]);
      return page.pdf({
        format: 'A4', printBackground: true, preferCSSPageSize: true, displayHeaderFooter: true,
        headerTemplate: '<span></span>', footerTemplate: footer, tagged: true, timeout: config.pdf.timeoutMs,
      });
    });
    return Buffer.from(pdf);
  } catch (err) {
    console.error(`[printouts] ${name} failed after ${Date.now() - started} ms: ${err.message}`);
    if (err.status) throw err;
    const e = new Error('The printout could not be made. Try again in a moment.');
    e.status = 500;
    e.cause = err;
    throw e;
  }
}

/** Today's date in Nigerian time, as 'dd/mm/yyyy' (for a heading's "Printed" or "As at"). */
const today = () => hbs.helpers.datetime(new Date()).slice(0, 10);
/** The same as 'yyyy-mm-dd', for a fact of kind date. */
const todayIso = () => today().split('/').reverse().join('-');

module.exports = { renderPdf, today, todayIso, close: browser.close, stats: browser.stats };
